CREATE TABLE "AffiliateMailSettings" ("id" TEXT PRIMARY KEY DEFAULT 'affiliate-email', "enabled" BOOLEAN NOT NULL DEFAULT false, "rulesConfirmed" BOOLEAN NOT NULL DEFAULT false, "rulesUrl" TEXT NOT NULL DEFAULT '', "startsAt" TIMESTAMP(3), "endsAt" TIMESTAMP(3), "footer" TEXT NOT NULL DEFAULT '', "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AffiliateMailAccount" ("id" TEXT PRIMARY KEY DEFAULT 'affiliate-email', "email" TEXT NOT NULL, "refreshToken" TEXT NOT NULL, "connectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AffiliateMailOAuth" ("stateHash" TEXT PRIMARY KEY, "userId" TEXT NOT NULL, "verifier" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AffiliateMailTemplate" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "trigger" TEXT NOT NULL, "milestone" INTEGER, "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "version" INTEGER NOT NULL DEFAULT 1, "approvedVersion" INTEGER, "approvedBy" TEXT, "approvedAt" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AffiliateMailContact" ("id" TEXT PRIMARY KEY, "code" TEXT NOT NULL, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "affiliateUrl" TEXT NOT NULL, "count" INTEGER NOT NULL, "previousCount" INTEGER NOT NULL, "baselineCount" INTEGER NOT NULL, "rank" INTEGER, "gap" INTEGER, "snapshotAt" TIMESTAMP(3) NOT NULL, "eligible" BOOLEAN NOT NULL DEFAULT false, "unsubscribedAt" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "AffiliateMailContact_code_key" ON "AffiliateMailContact"("code");
CREATE UNIQUE INDEX "AffiliateMailContact_email_key" ON "AffiliateMailContact"("email");
CREATE TABLE "AffiliateMailDelivery" ("id" TEXT PRIMARY KEY, "eventKey" TEXT NOT NULL, "contactId" TEXT NOT NULL, "templateId" TEXT NOT NULL, "templateVersion" INTEGER NOT NULL, "status" TEXT NOT NULL DEFAULT 'QUEUED', "subject" TEXT NOT NULL, "body" TEXT NOT NULL, "recipient" TEXT NOT NULL, "providerId" TEXT, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "attemptedAt" TIMESTAMP(3), "sentAt" TIMESTAMP(3));
CREATE UNIQUE INDEX "AffiliateMailDelivery_eventKey_key" ON "AffiliateMailDelivery"("eventKey");
CREATE INDEX "AffiliateMailDelivery_contactId_createdAt_idx" ON "AffiliateMailDelivery"("contactId", "createdAt");
CREATE INDEX "AffiliateMailDelivery_status_createdAt_idx" ON "AffiliateMailDelivery"("status", "createdAt");
